import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { ordersApi } from '../utils/api';
import toast from 'react-hot-toast';

const CAT_META = {
  starter:  { label: 'Salatlar va Sho\'rvalar', emoji: '🥗' },
  main:     { label: 'Asosiy Taomlar',          emoji: '🍽️' },
  dessert:  { label: 'Desertlar',               emoji: '🍰' },
  beverage: { label: 'Ichimliklar',             emoji: '🥤' },
  combo:    { label: 'Kompleks Ovqatlar',       emoji: '🎁' },
};

export default function OrderModal({ table, staffId, onClose }) {
  const { menu, staff } = useApp();
  const [cart, setCart] = useState([]);
  const [selectedStaff, setSelectedStaff] = useState(staffId || staff[0]?.id || '');
  const [submitting, setSubmitting] = useState(false);
  const [activeCategory, setActiveCategory] = useState('main');

  const waiters = staff.filter((s) => ['waiter', 'manager'].includes(s.role));
  const categories = [...new Set(menu.map((m) => m.category))];

  function addToCart(item) {
    setCart((prev) => {
      const existing = prev.find((c) => c.menuItemId === item.id);
      if (existing) return prev.map((c) => c.menuItemId === item.id ? { ...c, quantity: c.quantity + 1 } : c);
      return [...prev, { menuItemId: item.id, name: item.name, price: item.price, quantity: 1, notes: '' }];
    });
  }

  function changeQty(menuItemId, delta) {
    setCart((prev) => prev.map((c) => c.menuItemId === menuItemId ? { ...c, quantity: c.quantity + delta } : c).filter((c) => c.quantity > 0));
  }

  const total = cart.reduce((s, c) => s + c.price * c.quantity, 0);

  async function handleSubmit() {
    if (cart.length === 0) { toast.error("Kamida 1 ta taom tanlang"); return; }
    if (!selectedStaff) { toast.error("Ofitsiannt tanlang"); return; }
    setSubmitting(true);
    try {
      await ordersApi.create({
        tableId: String(table.id),
        staffId: selectedStaff,
        items: cart.map(({ menuItemId, quantity, notes }) => ({ menuItemId, quantity, notes })),
      });
      toast.success('Buyurtma oshxonaga yuborildi!');
      onClose();
    } catch (err) {
      toast.error(err.response?.data?.error || 'Xatolik yuz berdi');
    } finally {
      setSubmitting(false);
    }
  }

  const filteredMenu = menu.filter((m) => m.category === activeCategory);
  const cartCount = cart.reduce((s, c) => s + c.quantity, 0);

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal modal-lg" onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-amber-500/20 flex items-center justify-center text-xl">🍽️</div>
            <div>
              <h3 className="text-white font-bold text-lg">Buyurtma berish</h3>
              <p className="text-gray-500 text-sm">{table.id}-stol • {table.customerName}</p>
            </div>
          </div>
          <button onClick={onClose} className="text-gray-600 hover:text-gray-400 text-xl">✕</button>
        </div>

        <div className="flex gap-5 h-[65vh]">
          {/* Left: Menu */}
          <div className="flex-1 flex flex-col overflow-hidden">
            {/* Category tabs */}
            <div className="flex gap-2 mb-4 flex-wrap">
              {categories.map((cat) => {
                const meta = CAT_META[cat] || { label: cat, emoji: '🍴' };
                return (
                  <button
                    key={cat}
                    onClick={() => setActiveCategory(cat)}
                    className={`btn-sm flex items-center gap-1.5 ${activeCategory === cat ? 'btn-primary' : 'btn-ghost'}`}
                  >
                    <span>{meta.emoji}</span>
                    <span className="text-xs">{meta.label.split(' ')[0]}</span>
                  </button>
                );
              })}
            </div>

            {/* Items */}
            <div className="flex-1 overflow-y-auto space-y-2 pr-1">
              {filteredMenu.map((item) => {
                const inCart = cart.find((c) => c.menuItemId === item.id);
                return (
                  <div
                    key={item.id}
                    onClick={() => addToCart(item)}
                    className={`flex justify-between items-center rounded-xl p-3.5 cursor-pointer transition-all border ${
                      inCart
                        ? 'bg-violet-600/15 border-violet-500/40'
                        : 'bg-white/[0.03] border-white/[0.06] hover:bg-white/[0.07] hover:border-white/10'
                    }`}
                  >
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <p className="text-white font-medium text-sm truncate">{item.name}</p>
                        {inCart && (
                          <span className="badge bg-violet-500/30 text-violet-300 shrink-0">{inCart.quantity}x</span>
                        )}
                      </div>
                      {item.allergens?.length > 0 && (
                        <p className="text-xs text-orange-400/80 mt-0.5">⚠️ {item.allergens.join(', ')}</p>
                      )}
                    </div>
                    <span className="text-emerald-400 font-bold text-sm ml-3 shrink-0">${item.price.toFixed(2)}</span>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Right: Cart */}
          <div className="w-56 flex flex-col shrink-0">
            <div className="flex items-center justify-between mb-3">
              <h4 className="text-sm font-semibold text-gray-400">Savat</h4>
              {cartCount > 0 && (
                <span className="badge bg-violet-500/20 text-violet-400">{cartCount} ta</span>
              )}
            </div>

            <div className="flex-1 overflow-y-auto space-y-2">
              {cart.length === 0 && (
                <div className="text-center py-8">
                  <p className="text-3xl mb-2">🛒</p>
                  <p className="text-gray-600 text-xs">Taomlarni bosib savatga qo'shing</p>
                </div>
              )}
              {cart.map((item) => (
                <div key={item.menuItemId} className="bg-white/[0.04] border border-white/[0.06] rounded-xl p-3">
                  <p className="text-white text-xs font-medium leading-tight mb-2">{item.name}</p>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <button onClick={() => changeQty(item.menuItemId, -1)}
                        className="w-6 h-6 rounded-lg bg-white/10 hover:bg-white/20 text-white text-xs font-bold flex items-center justify-center">
                        −
                      </button>
                      <span className="text-white text-sm font-semibold w-4 text-center">{item.quantity}</span>
                      <button onClick={() => changeQty(item.menuItemId, 1)}
                        className="w-6 h-6 rounded-lg bg-white/10 hover:bg-white/20 text-white text-xs font-bold flex items-center justify-center">
                        +
                      </button>
                    </div>
                    <span className="text-emerald-400 text-xs font-bold">${(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                </div>
              ))}
            </div>

            {/* Total & submit */}
            <div className="border-t border-white/[0.08] pt-4 mt-3 space-y-3">
              <div className="flex justify-between items-center">
                <span className="text-gray-400 text-sm">Jami</span>
                <span className="text-emerald-400 font-bold text-lg">${total.toFixed(2)}</span>
              </div>
              <select className="input text-xs py-2" value={selectedStaff} onChange={(e) => setSelectedStaff(e.target.value)}>
                {waiters.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
              <button onClick={handleSubmit} disabled={submitting || cart.length === 0} className="btn btn-warning w-full">
                {submitting ? 'Yuborilmoqda...' : 'Oshxonaga yuborish'}
              </button>
              <button onClick={onClose} className="btn btn-ghost w-full text-xs">Bekor qilish</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
